import React from 'react';
import { Box, Avatar, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import HomeIcon from '@mui/icons-material/Home';
import NotificationsIcon from '@mui/icons-material/Notifications';
import ArticleIcon from '@mui/icons-material/Article';
import LogoutIcon from '@mui/icons-material/Logout';
import { utilisateurService } from '../../services/utilisateurService';

interface LeftMenuProps {
    utilisateur: {
        id: number;
        pseudo: string;
        photo_profil: string | null;
    };
    activeView: 'actualites' | 'mes_publications';
    onViewChange: (view: 'actualites' | 'mes_publications') => void;
}

const LeftMenu: React.FC<LeftMenuProps> = ({ utilisateur, activeView, onViewChange }) => {
    const navigate = useNavigate();

    const handleLogout = async () => {
        try {
            await utilisateurService.deconnexion();
            sessionStorage.clear();
            navigate('/login');
        } catch (error) {
            console.error('Erreur lors de la déconnexion', error);
        }
    };

    // Chemin local pour l'avatar
    const avatarUrl = utilisateur.photo_profil
        ? `/icons/${utilisateur.photo_profil}`
        : '/icons/green.jpg';

    return (
        <Box sx={{
            width: 280,
            background: 'linear-gradient(180deg, #ffffff 1%, #cfcfcf 43%, #999999 100%)',
            height: '100vh',
            position: 'relative',
            flexShrink: 0
        }}>
            {/* Logo - chemin local */}
            <Box sx={{ position: 'absolute', left: 40, top: 20 }}>
                <img src="/icons/logo.png" alt="Logo" style={{ width: 199, height: 122 }} />
            </Box>

            {/* Profil */}
            <Box sx={{ position: 'absolute', left: 97, top: 173 }}>
                <Avatar
                    src={avatarUrl}
                    sx={{ width: 86, height: 88, border: '3px solid white', boxShadow: '0 4px 10px rgba(0,0,0,0.2)' }}
                />
            </Box>
            <Typography sx={{
                position: 'absolute',
                left: 58,
                top: 274,
                width: 162,
                fontFamily: 'Poppins',
                fontWeight: 600,
                fontSize: 16,
                color: '#333',
                textAlign: 'center'
            }}>
                @{utilisateur.pseudo}
            </Typography>

            {/* Menu Actualités */}
            <MenuItem
                icon={<HomeIcon />}
                label="Actualités"
                isActive={activeView === 'actualites'}
                onClick={() => onViewChange('actualites')}
                top={387}
            />

            {/* Menu Notification */}
            <MenuItem
                icon={<NotificationsIcon />}
                label="Notification"
                isActive={false}
                onClick={() => {}}
                top={447}
            />

            {/* Menu Mes publications */}
            <MenuItem
                icon={<ArticleIcon />}
                label="Mes publications"
                isActive={activeView === 'mes_publications'}
                onClick={() => onViewChange('mes_publications')}
                top={507}
            />

            {/* Déconnexion */}
            <Box sx={{
                position: 'absolute',
                left: 40,
                bottom: 40,
                display: 'flex',
                alignItems: 'center',
                cursor: 'pointer',
                padding: '8px 12px',
                borderRadius: '12px',
                transition: 'all 0.3s ease',
                '&:hover': {
                    background: 'rgba(119, 51, 153, 0.15)',
                    transform: 'translateX(5px)'
                }
            }} onClick={handleLogout}>
                <LogoutIcon sx={{ width: 32, height: 32, color: '#666' }} />
                <Typography sx={{ ml: 2, fontFamily: 'Poppins', fontWeight: 600, fontSize: 16, color: '#333' }}>
                    Se déconnecter
                </Typography>
            </Box>
        </Box>
    );
};

interface MenuItemProps {
    icon: React.ReactNode;
    label: string;
    isActive: boolean;
    onClick: () => void;
    top: number;
}

const MenuItem: React.FC<MenuItemProps> = ({ icon, label, isActive, onClick, top }) => {
    return (
        <Box
            onClick={onClick}
            sx={{
                position: 'absolute',
                left: 40,
                top,
                display: 'flex',
                alignItems: 'center',
                cursor: 'pointer',
                padding: '8px 12px',
                borderRadius: '12px',
                transition: 'all 0.3s ease',
                background: isActive ? 'rgba(119, 51, 153, 0.2)' : 'transparent',
                borderLeft: isActive ? '3px solid #773399' : '3px solid transparent',
                '&:hover': {
                    background: 'rgba(119, 51, 153, 0.15)',
                    transform: 'translateX(5px)'
                },
                '&:hover .menu-icon': {
                    transform: 'scale(1.1)'
                },
                '&:hover .menu-text': {
                    color: '#773399'
                }
            }}
        >
            <Box className="menu-icon" sx={{
                width: 32,
                height: 32,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: isActive ? '#773399' : '#666',
                transition: 'transform 0.3s ease'
            }}>
                {icon}
            </Box>
            <Typography className="menu-text" sx={{
                ml: 2,
                fontFamily: 'Poppins',
                fontWeight: isActive ? 700 : 600,
                fontSize: 16,
                color: isActive ? '#773399' : '#333',
                transition: 'color 0.3s ease'
            }}>
                {label}
            </Typography>
        </Box>
    );
};

export default LeftMenu;
